import { MARQUEE } from "../config/component.config.js";
import { Aria } from "../utils/Aria.js";
import type {
  GsapGlobal,
  WindowWithGsap,
} from "../types/gsap.types.js";
import type {
  MarqueeElements,
  MarqueeInitOptions,
  MarqueeItem,
} from "../types/component.types.js";

function getGsap(): GsapGlobal | null {
  return (window as WindowWithGsap).gsap ?? null;
}

function toNumber(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  return parsed;
}

function resolveElements(root: HTMLElement): MarqueeElements | null {
  const viewport = root.querySelector<HTMLElement>(MARQUEE.viewportSelector);
  const track = root.querySelector<HTMLElement>(MARQUEE.trackSelector);
  const item = root.querySelector<HTMLElement>(MARQUEE.itemSelector);
  if (!viewport || !track || !item) return null;
  return { root, viewport, track, item };
}

class MarqueeItemRuntime {
  private readonly _elements: MarqueeElements;
  private readonly _speed: number;
  private readonly _pauseOnHover: boolean;
  private _groupWidth = 0;
  private _tween: { kill?: () => void; pause?: () => void; resume?: () => void } | null = null;
  private _clones: HTMLElement[] = [];
  private _resizeObserver: ResizeObserver | null = null;
  private _handleResize = (): void => this.refresh();
  private _handleMouseEnter = (): void => {
    if (!this._pauseOnHover) return;
    this._tween?.pause?.();
  };
  private _handleMouseLeave = (): void => {
    if (!this._pauseOnHover) return;
    this._tween?.resume?.();
  };

  constructor(item: MarqueeItem) {
    this._elements = item.elements;
    this._speed = item.speed;
    this._pauseOnHover = item.pauseOnHover;
  }

  init(): void {
    this.dispose();
    this._buildClones();
    this.refresh();
    window.addEventListener("resize", this._handleResize);
    this._elements.root.addEventListener("mouseenter", this._handleMouseEnter);
    this._elements.root.addEventListener("mouseleave", this._handleMouseLeave);
    this._observeResize();
  }

  refresh(): void {
    this._killTween();
    this._elements.track.style.transform = "translate3d(0, 0, 0)";
    this._buildClones();
    this._groupWidth = this._elements.item.offsetWidth;
    if (this._groupWidth <= 0) return;

    const duration = this._groupWidth / this._speed;
    const gsap = getGsap();
    if (!gsap) {
      this._elements.root.style.setProperty(
        MARQUEE.fallbackDurationVar,
        `${duration}s`,
      );
      this._elements.root.classList.add(MARQUEE.fallbackClass);
      return;
    }

    this._elements.root.classList.remove(MARQUEE.fallbackClass);
    this._tween = gsap.to(this._elements.track, {
      x: -this._groupWidth,
      duration,
      ease: "none",
      repeat: -1,
    }) as { kill?: () => void; pause?: () => void; resume?: () => void };
  }

  dispose(): void {
    window.removeEventListener("resize", this._handleResize);
    this._elements.root.removeEventListener("mouseenter", this._handleMouseEnter);
    this._elements.root.removeEventListener("mouseleave", this._handleMouseLeave);
    this._resizeObserver?.disconnect();
    this._resizeObserver = null;
    this._killTween();
    this._elements.root.classList.remove(MARQUEE.fallbackClass);
    this._elements.track.style.transform = "";
    this._elements.root.style.removeProperty(MARQUEE.fallbackDurationVar);
    this._clones.forEach((clone) => {
      if (clone.parentElement === this._elements.track) {
        this._elements.track.removeChild(clone);
      }
    });
    this._clones = [];
  }

  private _buildClones(): void {
    this._clones.forEach((clone) => {
      if (clone.parentElement === this._elements.track) {
        this._elements.track.removeChild(clone);
      }
    });
    this._clones = [];

    const itemWidth = this._elements.item.offsetWidth;
    const viewportWidth = this._elements.viewport.offsetWidth;
    if (itemWidth <= 0 || viewportWidth <= 0) return;

    const cloneCount = Math.max(1, Math.ceil(viewportWidth / itemWidth) + 1);
    for (let index = 0; index < cloneCount; index += 1) {
      const clone = this._elements.item.cloneNode(true) as HTMLElement;
      Aria.setHidden(clone, true);
      this._elements.track.appendChild(clone);
      this._clones.push(clone);
    }
  }

  private _observeResize(): void {
    if (typeof ResizeObserver === "undefined") return;
    this._resizeObserver = new ResizeObserver(() => this.refresh());
    this._resizeObserver.observe(this._elements.viewport);
    this._resizeObserver.observe(this._elements.item);
  }

  private _killTween(): void {
    this._tween?.kill?.();
    this._tween = null;
  }
}

export class Marquee {
  private static _items: MarqueeItemRuntime[] = [];

  static init(options: MarqueeInitOptions = {}): void {
    Marquee.dispose();
    const selector = options.selector ?? MARQUEE.selector;
    const root = options.root ?? document;
    const roots = Array.from(root.querySelectorAll<HTMLElement>(selector));
    if (roots.length === 0) return;

    Marquee._items = roots.flatMap((root) => {
      const elements = resolveElements(root);
      if (!elements) return [];
      return [
        new MarqueeItemRuntime({
          elements,
          speed: toNumber(root.dataset.marqueeSpeed, MARQUEE.speed),
          pauseOnHover:
            root.dataset.marqueePauseOnHover !== "false" &&
            MARQUEE.pauseOnHover,
        }),
      ];
    });

    Marquee._items.forEach((item) => item.init());
  }

  static dispose(): void {
    Marquee._items.forEach((item) => item.dispose());
    Marquee._items = [];
  }
}

